                  : <><UserCheck className="w-4 h-4" /> Add Staff Member</>}
            </button>
          </div>
        </form>
      </div>

      {/* ── Filter buttons ── */}
      <div className="flex gap-2 mb-4 flex-wrap">
        {FILTERS.map(f => (
