                      <td className="px-3 md:px-4 py-2">
                        <select value={editForm.employmentType} onChange={e => setEditForm(f => ({ ...f, employmentType: e.target.value }))} className="border border-gray-200 rounded px-2 py-1 text-xs bg-white">
