382	          </div>
383	        </SectionCard>
384	
385	        {/* ── AN-ACC Settings ── */}
386	        <SectionCard icon={DollarSign} title="AN-ACC Settings">
387	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
388	            <Field label="AN-ACC Rate per Resident (AUD/day)" hint="Default: $220.00. Update if your Base Care Tariff changes.">
389	              <div className="relative">
