1	'use client';
2	
3	import { useState, useMemo, useEffect, useCallback } from 'react';
4	import { Plus, Download, Upload, Pencil, Trash2, ClipboardList, X, Check, Database, RefreshCw } from 'lucide-react';
5	import { shifts as dummyShifts, staff as dummyStaff, facility } from '@/lib/dummyData';
6	import { calculateDayCompliance, formatAUD } from '@/lib/compliance';
7	import { getShifts, addShift, updateShift, deleteShift, getStaff, logShiftHistory, mapShift, mapStaff } from '@/lib/db';
8	import { SEED_FACILITY_ID } from '@/lib/seedData';
9	
10	// ─── Helpers ─────────────────────────────────────────────────────────────────
11	
12	function toIso(ddmmyyyy) {
13	  const [d, m, y] = ddmmyyyy.split('/');
14	  return `${y}-${m}-${d}`;
15	}
16	
17	function toDisplay(iso) {
18	  if (!iso) return '';
19	  const [y, m, d] = iso.split('-');
20	  return `${d}/${m}/${y}`;
21	}
22	
23	function calcDuration(start, end) {
24	  if (!start || !end) return 0;
25	  const [sh, sm] = start.split(':').map(Number);
26	  const [eh, em] = end.split(':').map(Number);
27	  const mins = (eh * 60 + em) - (sh * 60 + sm);
28	  return mins > 0 ? mins : 0;
29	}
30	
31	function fmtMins(m) {
32	  return `${Math.floor(m / 60)}h ${m % 60}m`;
33	}
34	
35	function getWeek(isoDate) {
36	  const d = new Date(isoDate);
37	  const day = d.getDay() || 7;
38	  d.setUTCDate(d.getUTCDate() + 4 - day);
39	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
40	  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
41	}
42	
43	const THIS_WEEK = getWeek('2026-04-02');
44	
45	const CSV_TEMPLATE = `Date (DD/MM/YYYY),Staff Name,Role,Start Time (HH:MM),End Time (HH:MM)
46	02/04/2026,Sarah Chen,RN,07:00,15:00
47	02/04/2026,Jennifer Walsh,EN,07:00,15:00
48	02/04/2026,David Kim,PCW,15:00,23:00
49	`;
50	
51	// ─── Page ─────────────────────────────────────────────────────────────────────
52	
53	export default function ShiftsPage() {
54	  // Data state — starts with dummy, replaced by DB on load
55	  const [shifts, setShifts]   = useState(dummyShifts);
56	  const [staff, setStaff]     = useState(dummyStaff);
57	  const [usingDb, setUsingDb] = useState(false);
58	  const [dbLoading, setDbLoading] = useState(true);
59	
60	  const [form, setForm]         = useState({ staffId: '', date: '02/04/2026', startTime: '', endTime: '' });
61	  const [editId, setEditId]     = useState(null);
62	  const [editForm, setEditForm] = useState({});
63	  const [auditId, setAuditId]   = useState(null);
64	  const [loading, setLoading]   = useState(false);
65	  const [success, setSuccess]   = useState(false);
66	
67	  // ── Load from Supabase ──────────────────────────────────────────────────────
68	  const loadFromDb = useCallback(async () => {
69	    setDbLoading(true);
70	    try {
71	      const [shiftsRes, staffRes] = await Promise.all([
72	        getShifts(SEED_FACILITY_ID),
73	        getStaff(SEED_FACILITY_ID),
74	      ]);
75	
76	      const dbOk = !shiftsRes.error && shiftsRes.data.length > 0 &&
77	                   !staffRes.error  && staffRes.data.length  > 0;
78	
79	      if (dbOk) {
80	        setShifts(shiftsRes.data.map(mapShift));
81	        setStaff(staffRes.data.map(mapStaff));
82	        setUsingDb(true);
83	      }
84	    } catch {
85	      // keep dummy data
86	    } finally {
87	      setDbLoading(false);
88	    }
89	  }, []);
90	
91	  useEffect(() => { loadFromDb(); }, [loadFromDb]);
92	
93	  const selectedStaff = staff.find(s => s.id === form.staffId);
94	  const duration      = calcDuration(form.startTime, form.endTime);
95	
96	  // This week's minutes
97	  const weekShifts = useMemo(() => shifts.filter(s => getWeek(s.date) === THIS_WEEK), [shifts]);
98	  const weekMinutes = weekShifts.reduce((a, s) => a + s.durationMinutes, 0);
99	  const weekTarget  = facility.residentCount * 215 * 7;
100	
101	  // Sorted shifts (newest first)
102	  const sortedShifts = useMemo(() =>
103	    [...shifts].sort((a, b) => b.date.localeCompare(a.date) || a.startTime.localeCompare(b.startTime)),
104	  [shifts]);
105	
106	  // ── Add shift ───────────────────────────────────────────────────────────────
107	  async function handleAdd(e) {
108	    e.preventDefault();
109	    if (!selectedStaff || !form.startTime || !form.endTime || duration <= 0) return;
110	    setLoading(true);
111	
112	    const isoDate = toIso(form.date);
113	    const newShift = {
114	      staffId:         form.staffId,
115	      staffName:       selectedStaff.name,
116	      staffType:       selectedStaff.role,
117	      date:            isoDate,
118	      startTime:       form.startTime,
119	      endTime:         form.endTime,
120	      durationMinutes: duration,
121	      employmentType:  selectedStaff.employmentType,
122	    };
123	
124	    if (usingDb) {
125	      const { data, error } = await addShift(SEED_FACILITY_ID, newShift);
126	      if (!error && data) {
127	        setShifts(prev => [...prev, mapShift(data)]);
128	      } else {
129	        // fall back: add locally with temp id
130	        setShifts(prev => [...prev, { id: `local-${Date.now()}`, ...newShift }]);
131	      }
132	    } else {
133	      setShifts(prev => [...prev, { id: `local-${Date.now()}`, ...newShift }]);
134	    }
135	
136	    setForm({ staffId: '', date: '02/04/2026', startTime: '', endTime: '' });
137	    setLoading(false);
138	    setSuccess(true);
139	    setTimeout(() => setSuccess(false), 2500);
140	  }
