                className="h-3 rounded-full transition-all duration-700"
                style={{
                  width: `${Math.min((weekMinutes / weekTarget) * 100, 100)}%`,
                  backgroundColor: weekMinutes >= weekTarget ? '#22c55e' : weekMinutes / weekTarget >= 0.85 ? '#f59e0b' : '#ef4444',
