            <p className="text-xs text-gray-400 mt-1">{((weekMinutes / weekTarget) * 100).toFixed(1)}% of weekly target</p>
          </div>
        </div>
      </div>

      {/* ── Add Shift Form ── */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 mb-6">
