                Penalty at risk today
              </span>
              <span className={`text-sm font-bold shrink-0 ${
                todayData.ragStatus === 'RED'   ? 'text-red-700' :
                todayData.ragStatus === 'AMBER' ? 'text-amber-700' :
                                                  'text-green-700'
