              </span>
            </div>
          </div>

          {/* 30-Day Trend Chart */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
            <h2 className="font-semibold text-gray-900 mb-4">30-Day Compliance Trend</h2>
